import {
  createCredential,
  generateIssuerKeyPair,
} from "@nexusid/sd-jwt/issuer";
import { buildPredicateClaims } from "@nexusid/sd-jwt/predicates";
import type { SDJWTCredential } from "@nexusid/types";
import type { AUStudentData } from "./portal-scraper";
import * as fs from "fs";
import * as path from "path";

function loadIssuerPrivateKey(): string {
  // 1. Try env var first (production / Docker secret)
  if (process.env.AU_ISSUER_PRIVATE_KEY) {
    return process.env.AU_ISSUER_PRIVATE_KEY.replace(/\\n/g, "\n");
  }

  // 2. Try PEM file (generated by scripts/generate-issuer-keys.ts)
  const keyPath = path.resolve(__dirname, "../.keys/.issuer-private-key.pem");
  if (fs.existsSync(keyPath)) {
    return fs.readFileSync(keyPath, "utf-8");
  }

  throw new Error(
    "AU issuer private key not found. " +
      "Set AU_ISSUER_PRIVATE_KEY env var or run scripts/generate-issuer-keys.ts",
  );
}

function deriveEnrollmentStatus(
  raw: string,
): "Active" | "Inactive" | "Graduated" | "Suspended" | "On Leave" {
  const normalized = raw.toLowerCase().trim();
  if (normalized.includes("active") || normalized.includes("enrolled"))
    return "Active";
  if (normalized.includes("graduat")) return "Graduated";
  if (normalized.includes("suspend")) return "Suspended";
  if (normalized.includes("leave")) return "On Leave";
  return "Inactive";
}

export async function buildCredential(
  auData: AUStudentData,
  userPublicKey: string,
): Promise<SDJWTCredential> {
  const privateKey = loadIssuerPrivateKey();

  // FR-007 AC3 / BR-021: only catalog predicates (FR-005 AC1 enrollment
  // group). Name, registration number, program and the exact CGPA never
  // enter the credential.
  const cgpa = Number(auData.cgpa);
  const hasCgpa = Number.isFinite(cgpa);
  const { claims, metadata } = buildPredicateClaims("au.edu.pk", {
    ENROLLED_CURRENT: deriveEnrollmentStatus(auData.enrollment_status) === "Active",
    CGPA_AT_LEAST_2_0: hasCgpa && cgpa >= 2.0,
    CGPA_AT_LEAST_3_0: hasCgpa && cgpa >= 3.0,
    CGPA_AT_LEAST_3_5: hasCgpa && cgpa >= 3.5,
  });

  const credential = await createCredential({
    claims,
    alwaysVisibleClaims: {
      credential_type: "enrollment",
      issuer_name: "Air University",
    },
    issuerDID: "au.edu.pk",
    holderPublicKey: userPublicKey,
    issuerPrivateKey: privateKey,
    keyId: "au-issuer-key-v1",
    expiresInDays: 365,
  });

  const enriched: SDJWTCredential = { ...credential, metadata };
  return enriched;
}
